def current_streak(cards: tuple[Card, ...], today: date) -> int:
    reviewed_dates = set()
    for card in cards:
        for event in card.history:
            reviewed_dates.add(event.reviewed_at.date())
    # Check if today has any event
    if today in reviewed_dates:
        current = today
        streak = 0
        while current in reviewed_dates:
            streak += 1
            current -= timedelta(days=1)
        return streak
    else:
        return 0

